wrong_code.class:
// Vulnerable traditional singleton:
// 1. Reflection can invoke the private constructor.
// 2. Deserializing an instance creates a new duplicate object.
import java.io.Serializable;

public class Elvis implements Serializable {
    public static final Elvis INSTANCE = new Elvis();

    private Elvis() {
        // No guard against reflection!
    }

    public void leaveTheBuilding() {
        System.out.println("Whoa baby, I'm outta here!");
    }
}

wrong_code.call_site:
import java.lang.reflect.Constructor;

public class Main {
    public static void main(String[] args) throws Exception {
        Elvis e1 = Elvis.INSTANCE;

        // Flaw: Reflection easily bypasses the private constructor!
        Constructor<Elvis> c = Elvis.class.getDeclaredConstructor();
        c.setAccessible(true);
        Elvis e2 = c.newInstance();

        System.out.println(e1 == e2); // false! Singleton contract broken!
    }
}

right_code.class:
// Single-element enum singleton:
// - Ironclad against reflection (JVM guarantees constructor cannot be invoked reflectively)
// - Serializable for free without readResolve()
public enum Elvis {
    INSTANCE;

    public void leaveTheBuilding() {
        System.out.println("Whoa baby, I'm outta here!");
    }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        Elvis elvis1 = Elvis.INSTANCE;
        Elvis elvis2 = Elvis.INSTANCE;

        System.out.println(elvis1 == elvis2); // true
        elvis1.leaveTheBuilding();
    }
}
